<?php
require_once __DIR__.'/includes/auth.php';requireRole('user');$uid=(int)$_SESSION['user_id'];
$q=$pdo->prepare("SELECT fitness_level,subscription_status,subscription_expires_at,dietary_preference FROM users WHERE id=?");$q->execute([$uid]);$u=$q->fetch();$premium=($u['subscription_status']==='active'&&$u['subscription_expires_at']&&$u['subscription_expires_at']>=date('Y-m-d'));$level=$u['fitness_level']==='advanced'?'expert':$u['fitness_level'];
$q=$pdo->prepare("SELECT * FROM diet_plans WHERE is_active=1 AND fitness_level=? AND (access_type='free' OR ?=1) AND (dietary_preference IS NULL OR dietary_preference='no_preference' OR dietary_preference=? OR ?='no_preference') ORDER BY access_type,title");$q->execute([$level,(int)$premium,$u['dietary_preference'],$u['dietary_preference']]);$diets=$q->fetchAll();
$q=$pdo->prepare("SELECT * FROM workout_templates WHERE is_active=1 AND fitness_level=? AND (access_type='free' OR ?=1) ORDER BY access_type,title");$q->execute([$level,(int)$premium]);$workouts=$q->fetchAll();
$assignedDiet=$pdo->prepare("SELECT d.* FROM user_plan_assignments a JOIN diet_plans d ON d.id=a.diet_plan_id WHERE a.user_id=? AND (a.ends_on IS NULL OR a.ends_on>=CURDATE()) AND (d.access_type='free' OR ?=1) ORDER BY a.created_at DESC");$assignedDiet->execute([$uid,(int)$premium]);$assignedDiets=$assignedDiet->fetchAll();
$assignedWorkout=$pdo->prepare("SELECT w.* FROM user_plan_assignments a JOIN workout_templates w ON w.id=a.workout_template_id WHERE a.user_id=? AND (a.ends_on IS NULL OR a.ends_on>=CURDATE()) AND (w.access_type='free' OR ?=1) ORDER BY a.created_at DESC");$assignedWorkout->execute([$uid,(int)$premium]);$assignedWorkouts=$assignedWorkout->fetchAll();
$q=$pdo->prepare('SELECT s.*,u.name admin_name FROM admin_suggestions s LEFT JOIN users u ON u.id=s.admin_id WHERE s.user_id=? ORDER BY s.created_at DESC');$q->execute([$uid]);$suggestions=$q->fetchAll();$pageTitle='My plans';require __DIR__.'/includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">PERSONALIZED GUIDANCE</p><h1>Your diet & workout plans</h1><p>Plans matched to your <?=e(ucfirst($level))?> level and membership.</p></div><span class="badge"><?=$premium?'Premium access':'Free access'?></span></section>
<?php if($suggestions):?><section class="panel"><h2>Suggestions from FitTrack admin</h2><?php foreach($suggestions as $s):?><article class="suggestion-card"><h3><?=e($s['title'])?></h3><p><?=nl2br(e($s['suggestion']))?></p><small><?=e($s['created_at'])?></small></article><?php endforeach;?></section><?php endif;?>
<div class="cols"><section class="panel"><h2>Diet guidance</h2><?php foreach($assignedDiets as $p):?><article class="suggestion-card"><span class="badge">Assigned by admin</span><h3><?=e($p['title'])?></h3><p><?=nl2br(e($p['description']??''))?></p><p><?=nl2br(e($p['guidance']??''))?></p></article><?php endforeach;?><?php if(!$diets):?><p>No matching diet plans are published yet. Please check back later or contact an administrator.</p><?php endif;?><?php foreach($diets as $p):?><article class="suggestion-card"><span class="badge"><?=e(ucfirst($p['access_type']))?></span><h3><?=e($p['title'])?></h3><p><?=nl2br(e($p['description']??''))?></p><p><?=nl2br(e($p['guidance']??''))?></p></article><?php endforeach;?></section><section class="panel"><h2>Workout guidance</h2><?php foreach($assignedWorkouts as $p):?><article class="suggestion-card"><span class="badge">Assigned by admin</span><h3><?=e($p['title'])?></h3><p><?=nl2br(e($p['description']??''))?></p><p><?=nl2br(e($p['schedule_text']??''))?></p><p><?=nl2br(e($p['guidance']??''))?></p></article><?php endforeach;?><?php if(!$workouts):?><p>No matching workout plans are published yet. Please check back later.</p><?php endif;?><?php foreach($workouts as $p):?><article class="suggestion-card"><span class="badge"><?=e(ucfirst($p['access_type']))?></span><h3><?=e($p['title'])?></h3><p><?=nl2br(e($p['description']??''))?></p><p><?=nl2br(e($p['schedule_text']??''))?></p><p><?=nl2br(e($p['guidance']??''))?></p></article><?php endforeach;?></section></div>
<?php require __DIR__.'/includes/footer.php';?>
